insert into hearthland.learning_topics (entity_id, category, description)
values
  ((select id from hearthland.entities where seed_key = 'demo:learning:creating-a-shared-vision' and is_seeded_demo), 'Community', 'Turn individual hopes into a practical direction a group can test.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:working-well-in-groups' and is_seeded_demo), 'Community', 'Simple agreements, feedback and conflict literacy for real shared work.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:water-on-the-land' and is_seeded_demo), 'Ecology', 'Read flows, retain water and choose appropriate small-scale systems.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:soil-and-biodiversity' and is_seeded_demo), 'Ecology', 'Build living soil while making space for productive, diverse habitats.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:permaculture-site-design' and is_seeded_demo), 'Permaculture & Food', 'Observe patterns and place systems where they reinforce one another.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:food-preservation' and is_seeded_demo), 'Permaculture & Food', 'Low-energy ways to preserve a seasonal harvest for community use.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:timber-construction' and is_seeded_demo), 'Building', 'Learn safe tools, joints, frames and weather protection on a real build.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:natural-building' and is_seeded_demo), 'Building', 'Work with timber, clay, fibre and stone in durable, repairable systems.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:cooperative-economy' and is_seeded_demo), 'Economy', 'Understand shared costs, ownership and viable community enterprises.'),
  ((select id from hearthland.entities where seed_key = 'demo:learning:practical-independence' and is_seeded_demo), 'Life', 'Repair, cook, care and organise with more confidence and less waste.')
on conflict (entity_id) do update
set category = excluded.category,
    description = excluded.description,
    updated_at = now();

insert into hearthland.building_camps (
  entity_id, host_entity_id, project_entity_id, location, country, region,
  start_date, end_date, purpose, full_description, max_participants,
