)
values
  ((select id from hearthland.entities where seed_key = 'demo:camp:bc-bohemia' and is_seeded_demo), (select id from hearthland.entities where seed_key = 'demo:emerging:e-morava' and is_seeded_demo), (select id from hearthland.entities where seed_key = 'demo:project:pr-morava' and is_seeded_demo), 'South Bohemia, Czechia', 'Czechia', null, '2026-09-12'::date, '2026-09-20'::date, 'Building · Community formation · Education · Permaculture', 'Nine days of building, learning and living together on the future settlement land. We will establish the first shared infrastructure and test the rhythms of community life.', 42, null, array[]::text[], 'Bring a tent or camper; a few basic indoor places are available.', 'Three vegetarian meals daily, prepared by rotating teams.', 'mixed', 'Volunteer exchange · €70 food contribution · supported places available', array['Participant', 'Learner', 'Volunteer', 'Builder', 'Master / Teacher', 'Future Resident']::text[], 'applications_open'),
  ((select id from hearthland.entities where seed_key = 'demo:camp:bc-serra' and is_seeded_demo), (select id from hearthland.entities where seed_key = 'demo:community:c-serra' and is_seeded_demo), null, 'Alentejo, Portugal', 'Portugal', null, '2026-10-03'::date, '2026-10-10'::date, 'Permaculture · Ecology · Land preparation', 'A practical week creating water-harvesting earthworks, a shaded outdoor classroom and the next agroforestry strip.', 30, null, array[]::text[], 'Tent, camper or community guest room.', 'Included; local vegetarian food.', 'mixed', '€190 fixed contribution · volunteer bursaries', array['Learner', 'Volunteer', 'Builder', 'Specialist']::text[], 'applications_open'),
  ((select id from hearthland.entities where seed_key = 'demo:camp:bc-karst' and is_seeded_demo), (select id from hearthland.entities where seed_key = 'demo:community:c-karst' and is_seeded_demo), null, 'Primorska, Slovenia', 'Slovenia', null, '2027-04-17'::date, '2027-04-25'::date, 'Building · Renovation · Community formation', 'Restore a dry-stone terrace, raise a greenhouse and complete the community’s small wood-fired sauna.', 36, null, array[]::text[], 'Shared indoor rooms, tents and vans.', 'Shared cooking; ingredients included.', 'donation', 'Donation-based', array['Participant', 'Builder', 'Master / Teacher', 'Future Resident']::text[], 'applications_open')
on conflict (entity_id) do update
set host_entity_id = excluded.host_entity_id,
    project_entity_id = excluded.project_entity_id,
    location = excluded.location,
    country = excluded.country,
    region = excluded.region,
    start_date = excluded.start_date,
    end_date = excluded.end_date,
    purpose = excluded.purpose,
    full_description = excluded.full_description,
    max_participants = excluded.max_participants,
    application_deadline = excluded.application_deadline,
    languages = excluded.languages,
    accommodation_type = excluded.accommodation_type,
    food_model = excluded.food_model,
    contribution_type = excluded.contribution_type,
    contribution_details = excluded.contribution_details,
    roles_available = excluded.roles_available,
    camp_status = excluded.camp_status,
    updated_at = now();

