update hearthland.camp_build_items
set description = 'Lead: Carpenter / builder',
    category = 'build',
    status = 'planned',
    target_participants_min = 8,
    target_participants_max = 12,
    updated_at = now()
where camp_entity_id = (select id from hearthland.entities where seed_key = 'demo:camp:bc-bohemia' and is_seeded_demo) and name = 'Covered community kitchen' and sort_order = 0;

insert into hearthland.camp_build_items (
  camp_entity_id, name, description, category, status,
  target_participants_min, target_participants_max, sort_order
)
select (select id from hearthland.entities where seed_key = 'demo:camp:bc-bohemia' and is_seeded_demo), 'Covered community kitchen', 'Lead: Carpenter / builder',
       'build', 'planned', 8, 12, 0
where not exists (
  select 1 from hearthland.camp_build_items where camp_entity_id = (select id from hearthland.entities where seed_key = 'demo:camp:bc-bohemia' and is_seeded_demo) and name = 'Covered community kitchen' and sort_order = 0
);

