from hearthland.camp_build_items build_item
where build_item.camp_entity_id = (select id from hearthland.entities where seed_key = 'demo:camp:bc-bohemia' and is_seeded_demo)
  and build_item.name = 'Covered community kitchen'
  and build_item.sort_order = 0
